-- Official KICD Grade 10 curriculum seed for the exam generator.
-- Source catalogue: https://kicd.ac.ke/cbc-materials/curriculum-designs/grade-ten/
-- Generated from 39 public KICD Grade 10 design covers and summary tables on 2026-10-13.
-- The Marine & Fisheries filename says Grade 11, but its official cover states Grade 10; the cover has governed this seed.
-- Idempotent: preserves legacy rows and adds only source-verified hierarchy and evidence rows.
BEGIN;

CREATE TEMP TABLE _kicd_g10_documents (
  document_order integer,
  subject_name text,
  subject_code text,
  category text,
  source_title text,
  source_url text
) ON COMMIT DROP;

SELECT gen_random_uuid(), 'KICD Grade 10 Curriculum Design — ' || d.subject_name, d.source_url, 'official_design', 'official_public', 'approved',
  'Grade 10 curriculum hierarchy extracted from the official public design summary table; catalogue category: ' || d.category || '; source file: ' || d.source_title
FROM _kicd_g10_documents d
WHERE NOT EXISTS (SELECT 1 FROM public.curriculum_sources cs WHERE cs.source_url = d.source_url);

SELECT g.id, d.subject_name, d.subject_code, cs.id
FROM _kicd_g10_documents d
JOIN public.curriculum_grades g ON g.grade_number = 10
LEFT JOIN public.curriculum_sources cs ON cs.source_url = d.source_url
WHERE NOT EXISTS (
  SELECT 1 FROM public.curriculum_subjects s
  WHERE s.grade_id = g.id AND lower(trim(s.subject_name)) = lower(trim(d.subject_name))
);

UPDATE public.curriculum_subjects s
SET subject_code = d.subject_code, curriculum_source_id = cs.id
FROM _kicd_g10_documents d
JOIN public.curriculum_grades g ON g.grade_number = 10
LEFT JOIN public.curriculum_sources cs ON cs.source_url = d.source_url
WHERE s.grade_id = g.id AND lower(trim(s.subject_name)) = lower(trim(d.subject_name));

CREATE TEMP TABLE _kicd_g10_seed (
  document_order integer,
  subject_name text,
  subject_code text,
  category text,
  source_title text,
  source_url text,
  strand_name text,
  strand_order integer,
  sub_strand_name text,
  sub_strand_order integer
) ON COMMIT DROP;

SELECT s.id, v.strand_name,
  'Official source-verified KICD Grade 10 strand. Source: ' || v.source_title || ' | ' || v.source_url,
  min(v.strand_order)
FROM _kicd_g10_seed v
JOIN public.curriculum_grades g ON g.grade_number = 10
JOIN public.curriculum_subjects s ON s.grade_id = g.id AND lower(trim(s.subject_name)) = lower(trim(v.subject_name))
WHERE NOT EXISTS (
  SELECT 1 FROM public.curriculum_strands st
  WHERE st.subject_id = s.id
    AND lower(trim(st.strand_name)) = lower(trim(v.strand_name))
    AND st.strand_description ~* '(official|source-verified)[[:space:]]+kicd'
)
GROUP BY s.id, v.strand_name, v.source_title, v.source_url;

SELECT st.id, v.sub_strand_name,
  'Official source-verified KICD Grade 10 sub-strand. Source: ' || v.source_title || ' | ' || v.source_url,
  min(v.sub_strand_order)
FROM _kicd_g10_seed v
JOIN public.curriculum_grades g ON g.grade_number = 10
JOIN public.curriculum_subjects s ON s.grade_id = g.id AND lower(trim(s.subject_name)) = lower(trim(v.subject_name))
JOIN public.curriculum_strands st ON st.subject_id = s.id
  AND lower(trim(st.strand_name)) = lower(trim(v.strand_name))
  AND st.strand_description ~* '(official|source-verified)[[:space:]]+kicd'
WHERE NOT EXISTS (
  SELECT 1 FROM public.curriculum_sub_strands ss
  WHERE ss.strand_id = st.id
    AND lower(trim(ss.sub_strand_name)) = lower(trim(v.sub_strand_name))
    AND ss.sub_strand_description ~* '(official|source-verified)[[:space:]]+kicd'
)
GROUP BY st.id, v.sub_strand_name, v.source_title, v.source_url;

CREATE TEMP TABLE _kicd_g10_topics (
  subject_name text,
  strand_name text,
  sub_strand_name text,
  topic_name text,
  topic_order integer,
  source_title text,
  source_url text
) ON COMMIT DROP;

SELECT ss.id, v.topic_name,
  'Official source-verified KICD Grade 10 content anchor. Source: ' || v.source_title || ' | ' || v.source_url,
  ARRAY[]::text[], min(v.topic_order)
FROM _kicd_g10_topics v
JOIN public.curriculum_grades g ON g.grade_number = 10
JOIN public.curriculum_subjects s ON s.grade_id = g.id AND lower(trim(s.subject_name)) = lower(trim(v.subject_name))
JOIN public.curriculum_strands st ON st.subject_id = s.id
  AND lower(trim(st.strand_name)) = lower(trim(v.strand_name))
  AND st.strand_description ~* '(official|source-verified)[[:space:]]+kicd'
JOIN public.curriculum_sub_strands ss ON ss.strand_id = st.id
  AND lower(trim(ss.sub_strand_name)) = lower(trim(v.sub_strand_name))
  AND ss.sub_strand_description ~* '(official|source-verified)[[:space:]]+kicd'
WHERE NOT EXISTS (
  SELECT 1 FROM public.curriculum_topics t
  WHERE t.sub_strand_id = ss.id
    AND lower(trim(t.topic_name)) = lower(trim(v.topic_name))
    AND t.topic_description ~* '(official|source-verified)[[:space:]]+kicd'
)
GROUP BY ss.id, v.topic_name, v.source_title, v.source_url;

CREATE TEMP TABLE _kicd_g10_evidence (
  subject_name text,
  source_title text,
  source_url text,
  strand_name text,
  sub_strand_name text,
  content_summary text
) ON COMMIT DROP;

SELECT 'KICD Grade 10 Curriculum Design — ' || v.subject_name, v.content_summary, v.subject_name, 'Grade 10', v.strand_name, v.sub_strand_name, true
FROM _kicd_g10_evidence v
WHERE NOT EXISTS (
  SELECT 1 FROM public.exam_knowledge_chunks ek
  WHERE ek.source_name = 'KICD Grade 10 Curriculum Design — ' || v.subject_name
    AND ek.subject = v.subject_name
    AND ek.grade_level = 'Grade 10'
    AND ek.strand IS NOT DISTINCT FROM v.strand_name
    AND ek.sub_strand IS NOT DISTINCT FROM v.sub_strand_name
);

COMMIT;
